class VaultDocumentFilter(django_filters.FilterSet):
    folder_id = django_filters.NumberFilter(method='filter_by_folder')

    class Meta:
        model = VaultDocument
        fields = ['folder_id']

    def filter_by_folder(self, queryset, name, value):
        return queryset.filter(folder_id=value, folder__vault__owner=self.request.user)

class VaultDocumentListView(generics.ListAPIView):
    serializer_class = VaultDocumentSerializer
    permission_classes = [permissions.IsAuthenticated]
    filter_backends = [DjangoFilterBackend]
    filterset_class = VaultDocumentFilter

    def get_queryset(self):
        return VaultDocument.objects.filter(vault__owner=self.request.user)
